// FASE 1: Almacenar acciones individuales
const actionData = $json;

// Validar estructura de acción
if (!actionData.type || !actionData.sessionId) {
  throw new Error('Invalid action data: missing type or sessionId');
}

// Enriquecer con metadata
const enrichedAction = {
  ...actionData,
  capturedAt: new Date().toISOString(),
  actionId: `action_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`
};

// Almacenar en contexto global para la sesión
const sessionId = actionData.sessionId;
const sessionKey = `session_${sessionId}`;

// Recuperar acciones existentes de la sesión
let sessionActions = $getWorkflowStaticData('node')[sessionKey] || [];

// Agregar nueva acción
sessionActions.push(enrichedAction);

// Guardar de vuelta
$getWorkflowStaticData('node')[sessionKey] = sessionActions;

console.log(`Action stored for session ${sessionId}. Total actions: ${sessionActions.length}`);

return [{
  json: {
    success: true,
    message: 'Action captured and stored',
    sessionId: sessionId,
    actionId: enrichedAction.actionId,
    totalActions: sessionActions.length,
    timestamp: enrichedAction.capturedAt
  }
}];

// FASE 2: Recuperar acciones almacenadas y procesar
const request = $json;
const sessionId = request.sessionId;

if (!sessionId) {
  throw new Error('Session ID is required for test generation');
}

const sessionKey = `session_${sessionId}`;
const sessionActions = $getWorkflowStaticData('node')[sessionKey] || [];

if (sessionActions.length === 0) {
  return [{
    json: {
      success: false,
      error: 'No actions found for this session',
      sessionId: sessionId
    }
  }];
}

// Validar mínimo de acciones
if (sessionActions.length < 3) {
  return [{
    json: {
      success: false,
      error: 'At least 3 actions required for test generation',
      sessionId: sessionId,
      currentActions: sessionActions.length
    }
  }];
}

// Preparar datos para procesamiento
const processedData = {
  sessionId: sessionId,
  totalActions: sessionActions.length,
  captureStartTime: sessionActions[0]?.capturedAt,
  captureEndTime: sessionActions[sessionActions.length - 1]?.capturedAt,
  sourceUrl: request.url || sessionActions[0]?.url || '',
  pageTitle: request.title || sessionActions[0]?.title || 'Test Session',
  userAgent: request.userAgent || 'TestBuilder Extension',
  actions: sessionActions.map((action, index) => ({
    ...action,
    actionIndex: index + 1,
    relativeTime: action.timestamp ? action.timestamp - sessionActions[0].timestamp : 0
  }))
};

console.log(`Processing ${sessionActions.length} actions for session ${sessionId}`);

return [{
  json: processedData
}];

