// Procesar respuesta de Playwright
const response = $json.candidates?.[0]?.content?.parts?.[0]?.text || '';

const cleanCode = response
  .replace(/```typescript/gi, '')
  .replace(/```javascript/gi, '')
  .replace(/```/g, '')
  .trim();

const isValidPlaywright = cleanCode.includes('page.') && 
                         (cleanCode.includes('test(') || cleanCode.includes('test.describe'));

if (!isValidPlaywright) {
  throw new Error('Generated code is not valid Playwright test');
}

return [{
  json: {
    testType: 'playwright',
    generatedCode: cleanCode,
    filename: `playwright-test-${Date.now()}.spec.ts`,
    sessionId: $('Retrieve Session Actions').item.json.sessionId,
    generatedAt: new Date().toISOString(),
    codeLength: cleanCode.length,
    linesCount: cleanCode.split('\n').length
  }
}];

// Procesar respuesta de CSV
const response = $json.candidates?.[0]?.content?.parts?.[0]?.text || '';

const cleanCsv = response
  .replace(/```csv/gi, '')
  .replace(/```/g, '')
  .trim();

const lines = cleanCsv.split('\n').filter(line => line.trim());
const hasHeader = lines[0] && lines[0].includes('Step') && lines[0].includes('Action');

if (!hasHeader || lines.length < 2) {
  throw new Error('Generated CSV is not valid');
}

return [{
  json: {
    testType: 'manual',
    generatedCsv: cleanCsv,
    filename: `manual-test-${Date.now()}.csv`,
    sessionId: $('Retrieve Session Actions').item.json.sessionId,
    generatedAt: new Date().toISOString(),
    stepsCount: lines.length - 1,
    csvSize: cleanCsv.length
  }
}];

// Crear respuesta final con cleanup de sesión
const playwrightData = $input.first()?.json || {};
const csvData = $input.last()?.json || {};
const originalData = $('Retrieve Session Actions').item.json;

// Limpiar datos de sesión después del procesamiento
const sessionKey = `session_${originalData.sessionId}`;
delete $getWorkflowStaticData('node')[sessionKey];

const finalResult = {
  success: true,
  sessionId: originalData.sessionId,
  message: 'Tests generated successfully from captured actions',
  timestamp: new Date().toISOString(),
  summary: {
    actionsProcessed: originalData.totalActions,
    playwrightGenerated: !!playwrightData.generatedCode,
    csvGenerated: !!csvData.generatedCsv,
    captureStartTime: originalData.captureStartTime,
    captureEndTime: originalData.captureEndTime
  },
  tests: {
    playwright: {
      filename: playwrightData.filename || '',
      linesCount: playwrightData.linesCount || 0,
      code: playwrightData.generatedCode || ''
    },
    manual: {
      filename: csvData.filename || '',
      stepsCount: csvData.stepsCount || 0,
      csv: csvData.generatedCsv || ''
    }
  },
  analysis: {
    totalDuration: originalData.captureEndTime && originalData.captureStartTime ? 
      new Date(originalData.captureEndTime) - new Date(originalData.captureStartTime) : 0,
    actionTypes: originalData.actions.reduce((acc, action) => {
      acc[action.type] = (acc[action.type] || 0) + 1;
      return acc;
    }, {})
  }
};

console.log(`Session ${originalData.sessionId} processed and cleaned up`);

return [{json: finalResult}];
